import { ROYALE_CARDS, royaleCard, type RoyaleCard } from "./yg-royale-cards";

export type RoyaleMatchupRelation = "strong" | "weak" | "even";
export type RoyaleMatchup = { relation: RoyaleMatchupRelation; reason: string };
export type RoyaleMatchupOpponent = { card: RoyaleCard; reason: string };

// Generated by scripts/verify-yg-royale-matchups.cjs --print-matrix.
// Each side uses one equal-level card, 140 world units apart, without tower fire.
// Only wins with at least 15% formation HP left, in both deployment directions,
// count as favorable. Touch/render handlers only read this table; no duel runs.
const MATCHUP_IDS = [
  "mega-chiaki", "ramen-negishi", "kawataka-squad", "goto-sinker", "kitazawa-archer",
  "ikehara-giant", "yamaki-bomber", "kawanabe-knight", "misawa-dragon", "kan-bats",
  "kobayashi-runner", "ishihata-spirits", "abe-guardian", "oshino-wizard",
  "nagayasu-sniper", "horie-golem", "shibata-dodger",
] as const;
const MATCHUP_ROWS = [
  "=++++=++--+++++=+", // mega-chiaki
  "-=+++-++=-+++++-+", // ramen-negishi
  "--=-+--=--+++-+-+", // kawataka-squad
  "--+==----+-+=---=", // goto-sinker
  "---==----=-+=---=", // kitazawa-archer
  "=++++=++--+++++-+", // ikehara-giant
  "--+++-=----+=---+", // yamaki-bomber
  "--=++-+=--+++++-+", // kawanabe-knight
  "+=++++++=+=++-=++", // misawa-dragon
  "+++-=+++-=+++--+-", // kan-bats
  "---++-+-=-=+=---+", // kobayashi-runner
  "-----------=-----", // ishihata-spirits
  "---==-=---=+=---+", // abe-guardian
  "--+++-+-+++++==-+", // oshino-wizard
  "---++-+-=++++==-+", // nagayasu-sniper
  "=+++++++--+++++=+", // horie-golem
  "---==----+-+----=", // shibata-dodger
] as const;
const INDEX = new Map<string, number>(MATCHUP_IDS.map((id, index) => [id, index]));

function advantage(winner: RoyaleCard, loser: RoyaleCard, unfavorable: boolean): string {
  if (winner.air && loser.targets === "ground") return unfavorable ? "飛行する相手に地上専用の攻撃が届かない。" : "飛行で地上専用の攻撃を受けずに削れる。";
  if (winner.splash > 0 && loser.count > 1) return unfavorable ? "相手の範囲攻撃で部隊をまとめて削られる。" : "範囲攻撃で部隊をまとめて削れる。";
  if (winner.count > 1 && loser.splash === 0) return unfavorable ? "複数の相手に囲まれ、単体攻撃が追いつきにくい。" : "複数で囲み、相手の単体攻撃を分散できる。";
  if (winner.trait === "shield" && loser.damage >= 180) return unfavorable ? "相手のシールドに大きな一撃を受け止められる。" : "シールドで強い一撃を受け止めて戦える。";
  if (winner.trait === "charge") return unfavorable ? "相手の突撃と高い単体火力に押されやすい。" : "突撃と高い単体火力で押し切りやすい。";
  if (winner.hp >= loser.hp * 1.6) return unfavorable ? "相手の厚い体力を削り切る前に押されやすい。" : "厚い体力で攻撃を受け止め、接近して押し切れる。";
  if (winner.range - loser.range >= 50) return unfavorable ? "射程差で先に削られ、接近する間に不利になる。" : "射程差で、接近される前から攻撃を重ねられる。";
  if (winner.trait === "slow") return unfavorable ? "相手の減速で足を止められ、攻撃を重ねられる。" : "減速で足を止めながら攻撃を重ねられる。";
  return unfavorable ? "各1枚では相手の火力と耐久力に押されやすい。" : "各1枚では火力と耐久力の組合せで押し切りやすい。";
}

/** One-card reference matchup; placement, elixir cost, tower fire and waves matter. */
export function royaleMatchup(attackerCardId: string, defenderCardId: string): RoyaleMatchup {
  const attacker = royaleCard(attackerCardId);
  const defender = royaleCard(defenderCardId);
  const ownIndex = INDEX.get(attackerCardId);
  const enemyIndex = INDEX.get(defenderCardId);
  if (ownIndex === undefined || enemyIndex === undefined) throw new Error("キャラクターの相性を確認してください。");
  const value = MATCHUP_ROWS[ownIndex][enemyIndex];
  if (value === "+") return { relation: "strong", reason: advantage(attacker, defender, false) };
  if (value === "-") return { relation: "weak", reason: advantage(defender, attacker, true) };
  return { relation: "even", reason: attackerCardId === defenderCardId ? "同じ能力。配置と味方の支援で差がつく。" : "各1枚では決定的な差が小さく、配置や支援次第。" };
}

export function royaleMatchups(cardId: string): { strong: RoyaleMatchupOpponent[]; weak: RoyaleMatchupOpponent[] } {
  royaleCard(cardId);
  const result: { strong: RoyaleMatchupOpponent[]; weak: RoyaleMatchupOpponent[] } = { strong: [], weak: [] };
  for (const card of ROYALE_CARDS) {
    const matchup = royaleMatchup(cardId, card.id);
    if (matchup.relation !== "even") result[matchup.relation].push({ card, reason: matchup.reason });
  }
  return result;
}
